// @name JSX: Colors
// @background #18181b
// @refresh 3600
// Tailwind's palette, picked by tapping. The classes are read when the frame
// draws, so `bg-${hue}-${shade}` works for every hue and shade.
const hues = ['red', 'orange', 'amber', 'yellow', 'lime', 'green', 'emerald', 'teal', 'cyan',
  'sky', 'blue', 'indigo', 'violet', 'purple', 'fuchsia', 'pink', 'rose', 'stone']
const shades = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950]

let hue = 'sky'
let shade = 500

export function get(app) {
  const ink = shade < 400 ? 'text-black/80' : 'text-white'
  return (
    <div className="flex flex-col gap-3 p-5 bg-zinc-900 text-white">
      <div className={`flex flex-col justify-end h-36 rounded-3xl p-5 bg-${hue}-${shade} ${ink}`}>
        <span className="text-sm uppercase opacity-70 font-semibold">Tap a color</span>
        <span className="text-3xl font-mono">{`bg-${hue}-${shade}`}</span>
      </div>
      <div className="flex gap-1 h-12">
        {shades.map((s) => (
          <div className={`flex-1 rounded-lg bg-${hue}-${s} ${s === shade ? 'border-4 border-white' : ''}`}
            onClick={() => { shade = s }} />
        ))}
      </div>
      <div className="flex-1 grid grid-cols-6 gap-2">
        {hues.map((h) => (
          <div className={`rounded-xl bg-${h}-500 ${h === hue ? 'border-4 border-white' : 'active:border-4 active:border-white/50'}`}
            onClick={() => { hue = h }} />
        ))}
      </div>
    </div>
  )
}
